const golfPreview=document.querySelector('#golf-preview'),gctx=golfPreview.getContext('2d');
let golfColor='Deep blue',golfView='rear',generation=0;const loaded={};
async function paintGolf(){const token=++generation;const src=`golf-${golfView}.png`;if(!loaded[src])loaded[src]=new Promise((resolve,reject)=>{const im=new Image();im.onload=()=>resolve(im);im.onerror=reject;im.src=src});try{const im=await loaded[src];if(token!==generation)return;gctx.drawImage(im,0,0,1774,887);if(golfColor!=='Deep blue'){const pixels=gctx.getImageData(0,0,1774,887),d=pixels.data;for(let i=0;i<d.length;i+=4){const r=d[i],g=d[i+1],b=d[i+2];if(d[i+3]>0&&b>r*1.25&&b>g*1.12){const l=.21*r+.72*g+.07*b;const c=golfColor==='Silver'?Math.min(255,l*1.4):l*.5;d[i]=d[i+1]=d[i+2]=c}}gctx.putImageData(pixels,0,0)}golfPreview.setAttribute('aria-label',`${golfColor} Golf R Mk7, ${golfView} view`);document.querySelector('.golf-selection').textContent=`${golfColor} · ${golfView==='rear'?'Rear':'Front'} view`;}catch{document.querySelector('.golf-selection').textContent='Preview unavailable. Please reload.'}}
document.querySelectorAll('[data-view]').forEach(button=>button.addEventListener('click',()=>{golfView=button.dataset.view;document.querySelectorAll('[data-view]').forEach(b=>{b.classList.toggle('selected',b===button);b.setAttribute('aria-pressed',String(b===button));});paintGolf();}));
document.querySelectorAll('.golf-colors button').forEach(button=>button.addEventListener('click',()=>{golfColor=button.dataset.color;document.querySelectorAll('.golf-colors button').forEach(b=>{b.classList.toggle('selected',b===button);b.setAttribute('aria-pressed',String(b===button));});paintGolf();}));paintGolf();
